// Reused unchanged nugget artwork and popup content from the original creator atlas.
export const nugget='<svg aria-hidden="true" viewBox="0 0 32 32"><path d="M6 10 15 4 24 7 28 19 21 27 9 26 3 18Z" fill="#dba12c" stroke="#76501c" stroke-width="1.5"/><path d="m6 10 9-6 3 10-9 5Z" fill="#ffe18a"/><path d="m18 14 6-7 4 12-7 8Z" fill="#bd7d1c"/><path d="m9 19 9-5 3 13-12-1Z" fill="#edbd4b"/><path d="m10 10 4-2" stroke="#fff2b0" stroke-width="2" stroke-linecap="round"/></svg>';
export function creatorPlacements(people,regionFor=p=>p.regions[0]){const placements=new Map(),groups=new Map();for(const p of people){const r=regionFor(p);if(r){if(!groups.has(r.label))groups.set(r.label,[]);groups.get(r.label).push(p);}}for(const group of groups.values()){group.sort((a,b)=>a.slug.localeCompare(b.slug));group.forEach((p,i)=>{const r=regionFor(p),angle=i*2.399963229728653,radius=group.length===1?0:0.65*Math.sqrt(i+1);placements.set(p.slug,[r.lat+Math.sin(angle)*radius,r.lng+Math.cos(angle)*radius/Math.cos(r.lat*Math.PI/180)]);});}return placements;}
export function creatorPopup(p,doc=document){const content=doc.createElement('div'),heading=doc.createElement('strong'),note=doc.createElement('p'),intro=doc.createElement('p'),link=doc.createElement('a');heading.textContent=p.name;intro.textContent=p.introduction;note.textContent=p.location+' — approximate regional placement, not a prospecting site.';link.href=p.profileUrl||'/prospectors/'+encodeURIComponent(p.slug)+'/';link.textContent='View creator profile →';content.append(heading,intro,note,link);if(p.videoCount>0){const videos=doc.createElement('a');videos.className='creator-video-link';videos.href='/prospectors/'+encodeURIComponent(p.slug)+'/videos/';videos.dataset.videoLibrary='';videos.dataset.creatorSlug=p.slug;videos.setAttribute('aria-haspopup','dialog');videos.setAttribute('aria-label','Video library for '+p.name+' · '+p.videoCount+' video'+(p.videoCount===1?'':'s'));videos.textContent='▶ Video library · '+p.videoCount;content.append(videos);}return content;}
export function creatorMarker(L,p,position,popupOptions={}){return L.marker(position,{title:p.name+' — '+(p.mapRegion||p.regions[0]).label,alt:p.name,icon:L.divIcon({className:'map-nugget',html:nugget,iconSize:[18,18],iconAnchor:[9,9]})}).bindTooltip(p.name,{direction:'top'}).bindPopup(creatorPopup(p),popupOptions);}
let leaflet;
export function loadLeaflet(){if(window.L)return Promise.resolve(window.L);if(leaflet)return leaflet;leaflet=new Promise((resolve,reject)=>{if(!document.querySelector('[data-creator-leaflet]')){const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';css.dataset.creatorLeaflet='';document.head.append(css);}const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.onload=()=>resolve(window.L);script.onerror=reject;document.head.append(script);});return leaflet;}
